def remove_invalid_parentheses(s):
    remove_left = remove_right = 0
    for ch in s:
        if ch == '(':
            remove_left += 1
        elif ch == ')':
            if remove_left > 0:
                remove_left -= 1
            else:
                remove_right += 1

    n = len(s)
    results = set()

    def backtrack(index, path, open_count, remove_left, remove_right):
        if index == n:
            if remove_left == 0 and remove_right == 0 and open_count == 0:
                results.add(''.join(path))
            return
        ch = s[index]
        if ch == '(' and remove_left > 0:
            backtrack(index + 1, path, open_count, remove_left - 1, remove_right)
        if ch == ')' and remove_right > 0:
            backtrack(index + 1, path, open_count, remove_left, remove_right - 1)

        path.append(ch)
        if ch != '(' and ch != ')':
            backtrack(index + 1, path, open_count, remove_left, remove_right)
        elif ch == '(':
            backtrack(index + 1, path, open_count + 1, remove_left, remove_right)
        elif open_count > 0:
            backtrack(index + 1, path, open_count - 1, remove_left, remove_right)
        path.pop()

    backtrack(0, [], 0, remove_left, remove_right)
    return sorted(results)

